fn reverse(v: &mut Vec<u64>) {
    let mut left = 0;
    let mut right = v.len().saturating_sub(1); // Use saturating_sub to handle empty vector

    while left < right {
        // Swap the elements at left and right indices
        v.swap(left, right);
        // Move the pointers towards the center
        left += 1;
        right -= 1;
    }
}